from .common import *
import pandas as pd
def table(head,rows):
    return '\n'.join(['| '+' | '.join(head)+' |','|'+'|'.join(['---']*len(head))+'|',*['| '+' | '.join(map(str,row))+' |' for row in rows]])
def main():
    a=pd.read_csv(D/'METRICS_BY_YEAR.csv');p=pd.read_csv(D/'POOLED_METRICS.csv');b=pd.read_csv(D/'PAIRED_COMPARISONS.csv');params=pd.read_csv(D/'MODEL_PARAMETERS.csv')
    order=['XAI/C039','XAI/anchor','PROBoost/IPCW','Stacking/IPCW'];names=['XAI-RSF C039*','XAI-RSF 固定种子','PROBoost-H','Chen Stacking-H'];labels=dict(zip(order,names))
    doc=['# ST 后先退市：两项 ESWA 方法的固定时限适配比较',
    '**C039 的 12 个月年内 AUC 最高（0.8377），PROBoost 的跨年合并 AP 最高（0.4586）。** 前 20% 捕获数为 C039 13/25、PROBoost 11/25、Chen Stacking 10/25。C039 与两种分类器的年内 AUC 配对差值区间均高于 0，但与 PROBoost 的 AP 差值区间包含 0，与两者的捕获数差值区间也都包含 0。换成事先固定的 96 树锚点，XAI-RSF 对 PROBoost 的年内 AUC 差值区间也包含 0。可以报告排序有竞争力、全局 CIF 二阶解释精确；证据不足以宣称预测全面优于近期分类方法。', '## 年度结果',
    '同一行统计的都是同一批企业。每格依次为 AUC、AP、Top20 捕获数/该窗真实退市数。2025 年 24 个月给全部 53 家导出了私有评分，因随访不足，公开性能保留 NA。']
    rows=[]
    for h,year in [(h,y) for h in [12,24] for y in YEARS]:
        z=a[(a.scope==year)&(a.months==h)].set_index('model');rr=[year,h,int(z.iloc[0].n)]
        for m in order:
            x=z.loc[m];rr.append(f'{x.auc:.4f} / {x.ap:.4f} / {int(x.top20_captured)}/{int(x.target_events)}' if x.status=='supported' else 'NA')
        rows.append(rr)
    doc.append(table(['入组年','月','企业数',*names],rows))
    doc+=['*C039 是在同一批已暴露队列的 120 个候选三种子组合中按 12 个月年内 AUC 选出的（POST_SELECTED_EXPLORATORY）。固定种子锚点为 42/101/202，和 C039 一样是 74 项输入、96 棵树及退市支持保护。两种分类器在各年分别独立训练 H12、H24，上表为训练 IPCW 主口径。2023 年仅 4 例 12 个月退市，PROBoost 4/4、Stacking 3/4、C039 2/4。2024 和 2025 年 12 个月均由 C039 捕获更多。', '## 合并排序、AP 和核查工作量']
    rows=[]
    for h in [12,24]:
        for m in order:
            z=p[(p.months==h)&(p.model==m)].iloc[0];rows.append([h,labels[m],f'{z.within_year_auc:.4f}',f'{z.auc:.4f}',f'{z.ap:.4f}',f'{int(z.top20_captured)}/{int(z.target_events)}',f'{100*z.precision20:.1f}%',f'{z.lift20:.2f}'])
    doc+=[table(['月','模型','年内 AUC','跨年 AUC','合并 AP','捕获','Precision@Top20','Lift'],rows),'12 个月共有 134 家、25 例退市，年度名额 8、9、11，共核查 28 家。24 个月取 2023/2024 共 81 家、32 例退市，核查 17 家。并列按冻结企业样本键升序处理。Lift 为核查名单命中率除以对应评价范围的观察发生率。年内 AUC 只比较同年的事件/非事件，按配对数加权。跨年 AUC、AP 在拼接的公司评分上重新计算。C039 与 PROBoost 的 12 个月跨年 AUC 很接近（0.6983 / 0.6950）；按所有公司的排名计算，PROBoost 把部分实际事件放在榜首的能力更强，因而得到更高的合并 AP。', '## 固定预测的配对不确定性']
    rows=[]
    for h,l,r,m in [(h,l,r,m) for h in (12,24) for l in ('XAI/C039','XAI/anchor') for r in ('PROBoost/IPCW','Stacking/IPCW') for m in ('within_year_auc','ap','top20_captured')]:
        z=b[(b.scope=='pooled')&(b.months==h)&(b.left==l)&(b.right==r)&(b.metric==m)].iloc[0];rows.append([h,labels[l]+' − '+labels[r],{'within_year_auc':'年内 AUC','ap':'合并 AP','top20_captured':'捕获家数'}[m],f'{z.estimate:+.4f}',f'[{z.lower95:+.4f}, {z.upper95:+.4f}]'])
    doc+=[table(['月','对照','指标','差值','条件 95% 区间'],rows),'重用原 1,000 次按入组年份分层的同一组公司抽样索引，固定所有预测和选种结果。捕获数区间由整数重抽结果取百分位，线性插值可以出现小数。区间不纳入训练、参数/特征选择及 C039 事后选优的不确定性。没有根据结果更改参数或核查阈值。',
    '## 数据时钟、训练集及删失',
    '每个 1 月 1 日截止点仅用此前已入组并核定到当时的状态、时间和冻结的 74 项输入；入组原点为财务／审计 ST 公告后的下一交易日开盘前。训练期独立公司为 309、345、390 家。训练分类器的已知 H12 标签为 277、313、359 个，其中退市 5、9、23 例；H24 已知为 260、301、347 个，其中退市 14、26、49 例。提前删失均由行政截止造成。早于恢复的退市为正例，先恢复为已知非退市。每期的恢复、足期无事件、删失天数范围和未成熟但已发生结局的数量见 CENSORING_AND_LABEL_AUDIT、MATURITY。',
    '三套年度外层均按时间外评价。由于最早期限只有 5 个训练退市，内部调参与元学习采用截止日前公司的分层分折，每家公司只占一行。内部折可以混合既往入组年份，不解读为额外的滚动时间外验证。对每个拟合折使用其全部随访估计反向 KM，用已知结局在事件时间或 H 的左极限计算监督权重，无正值时停止。提前删失不产生正/负监督标签。中位数、尺度、IG、IPSO、SMOTE、Hyperopt 和 GA 都限定在相应训练分区。公司级监督样本数绝不包含合成点。',
    '支持评价窗口的每家企业均有可判定的真实结局，主表直接比较全体已知记录，无需由评价标签拟合删失分布。在附加核对中，仅将各自训练期的 G 迁移到对应测试年，得 12 月年内 AUC 0.8345（C039）、0.7889（固定锚点）、0.7167（PROBoost）、0.6519（Stacking）。排序结论未反向。这是额外的加权口径，并不使历史删失与新队列删失自动可交换。初次只读核对曾调用既有评价器计算测试队列删失诊断；正式代码已改为直接核验结局是否完整，未将该诊断用于任何模型的学习、配置或最终权重。',
    '单独的完整结局敏感性仍排除未知结局，但对能判定的真实企业给予相同监督权重，重新执行两种分类方法的全流程。两者 12 个月年内 AUC 分别为 0.7524 和 0.7398，AP 为 0.4739 和 0.1881，捕获 11 和 10 例。24 个月对应 AUC 为 0.6218 和 0.6523，捕获均为 10 例。各口径分表列示；不能把未知企业视为正常，或把这些分类器的固定时限分数当作两原因 CIF。财务历史版本、部分审计字段的实时可得性以及 74 列名单的历史选择限制仍然存在。',
    '## 方法忠实性、计算和稳定性',
    'PROBoost 按 Liu 论文式 (3)–(8) 实现跨轮次变化的边界斜率、位移、交叉熵和一二阶更新，保留真正的二阶树生长，每次拟合 48 轮。完整数据、预处理、初值、终点和搜索规模做了适配。Chen 版本采用全文核验的乘法惯性更新、全粒子群重置、平均折 F1 和归一权重、3–5 个学习器的染色体约束。五个基学习器分别进行真实 Hyperopt 搜索，GA 用折外得分选择，二分类 LR 只拟合不含该公司的计划产生的 OOF 行。它是小预算、带支持回退的源论文二分类重实现；没有作者官方代码可供逐位复现。两篇论文的原数据、原任务和原性能数字均没有复刻。',
    '主 IPCW 分支共有 6 个 PROBoost 部署模型和 6 个 Stacking 部署模型。另有相同数量的完整结局敏感性模型。两种口径 PROBoost 各有 144 次历史调参拟合、6 次最终拟合，合计 14,400 个真实树更新。主 IPCW Stacking 的 10,918 次拟合分别为 IPSO 代理模型 6,664、Hyperopt 基模型 3,120（1,560 个提议、每个两折）、GA 候选元模型 308、基础重拟合 820、最终元模型 6。完整结局 Stacking 分别为 6,712、3,120、308、820、6，合计 10,966。正式结果对应 22,184 次拟合；连同保留的初次被替代运行 548 次，共实际执行 22,732 次。基础估计器的每棵组成树不重复算作一次拟合。XAI-RSF 新拟合 0 次。',
    'Slurm 为两节点池分配资源，24 个首轮任务和 2 个修复任务实际均在 oliver 执行并完成哈希核对。首批作业用时 51.5 秒（含排队），修复批次 7.3 秒。跨六个年度/时限任务，主 IPCW PROBoost 与 Stacking 的任务时间合计约 6.7 和 117.0 秒；任务并行，合计值不代表等待时间。模型文件大小、单次预测耗时和各阶段搜索次数见 RUNTIME_AND_COMPLEXITY、SEARCH_BUDGET；森林的历史训练时间与本轮调参总耗时分列。',
    '主 IPCW Stacking 的最终 H12 依次选中 12、15、12 项。三年共同入选总资产周转率及近一个月最大回撤，年度子集 Jaccard 为 0.143–0.286。H24 依次选中 11、16、11 项，三年没有共同项；2023 与 2025 的集合没有重叠。完整最终名单及每个元验证折名单逐项见 SELECTED_FEATURES。2023 年 H12 的 242 次代理/基模型拟合均未达到 SMOTE 最少 6 例的门槛。2025 年 H12 主 Stacking 仅形成 7 个不同评分。样本数、年份、制度环境及标签比例一起变化，不能从这些比较单独估计增加训练样本数的效应。',
    '## 解释性质与适用范围',
    '对 C039 与固定锚点重新核验了全部训练／评价行、所有原生时点和两个原因。C039 每年 55–59 个非零主效应、120–134 个非零二元函数即可恢复预测，最大绝对误差 1.56×10⁻¹⁵ 以下。所有原因曲线非负不降，同一时点原因和不超过 1。对比分类器 H12 与 H24 分别学习，没有这项跨原因与时间的一致性约束。PROBoost 可以在明确背景和输出尺度下用 TreeSHAP 精确归因原始 margin；这不等同于在最后非线性评分尺度上给每个原始变量和变量对导出完整函数。Stacking 的元对数几率在基学习器输出上可逐项求和，但这些项不直接给出企业变量层面的全局二阶函数。本轮没有运行 SHAP 或训练任何解释代理。',
    '## 研究判断与未完成项',
    '**Q1–Q3。** 2023 年 H12 的 PROBoost 和 Stacking 均优于 C039；2024 和 2025 年 H12 的年内排序与前 20% 捕获更有利于 C039。三年合并 AP 有利于 PROBoost。次要 H24 在两个可用队列合并时，C039 三项点估计均高于两个分类器，捕获数的差值区间仍包含 0。',
    '**Q4–Q5。** 全局二阶 CIF 表和可追溯的公司贡献体现了额外的方法性质。一个森林可以同时给出相互兼容的先恢复、先退市概率，而分类基线回答各自固定时限的排序问题。不能由模型解释推断财务变量的因果作用，也不能由这项比较声称原森林概率已校准。',
    '**Q6。** 用每年训练企业原始缺失比例中位数划分测试企业，H12 合并低/高缺失组中 PROBoost 的 AP 为 0.579/0.417，Stacking 为 0.211/0.161；两者对应的低/高组 AUC 分别为 0.689/0.699、0.452/0.526。各组的退市基数、年份构成不同，结果只作描述，不证明缺失或样本量引起了差异。事件不足的分层单元保留 NA。',
    '**Q7–Q8。** 既有 120 组同预算三种子森林的 H12 年内 AUC 中位数为 0.7951（P05–P95 0.7740–0.8246）。C039 高出其中位数约 0.043；这衡量已评候选间的差异，不能当作无偏的乐观偏差校正值。固定 96 树锚点的 AUC 为 0.7921，与 PROBoost 的差 +0.0709，区间 −0.0424 至 +0.1855。可以将具有竞争力的排序和原生函数结构同时写入 ESWA 论文，不能宣布在未见数据上全面胜出。',
    '2025 年 H24 只有评分，没有正式性能。未进行可选三状态模型或 SHAP 对照。首次 Stacking 核验发现小样本 GA 回退需修正，原结果及额外拟合量见 SUPERSEDED_JOBS；未筛去低分年度或不利指标。']
    (D/'RESULTS_ZH.md').write_text('\n\n'.join(doc)+'\n')
if __name__=='__main__':main()
